# hypothesis: output = input + point reflections of non-anchor color cells through anchor bbox center, no removals
def f(g):
    H,W=len(g),len(g[0])
    cnt=C(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    other=set(cnt)-{bg}
    # anchor = 2x2 solid smallest count
    anchor=min(other,key=lambda k:cnt[k]); scat=[o for o in other if o!=anchor][0]
    ap=[(r,c) for r in range(H) for c in range(W) if g[r][c]==anchor]
    ax=(min(r for r,_ in ap)+max(r for r,_ in ap))/2
    ay=(min(c for _,c in ap)+max(c for _,c in ap))/2
    sp=[(r,c) for r in range(H) for c in range(W) if g[r][c]==scat]
    out=[row[:] for row in g]
    refl={(r,c) for r in range(H) for c in range(W) if any((rr,cc) in {(int(ax*2-r,int(round(ay*2-c))),)} for rr,cc in [])} 
    refl=set()
    for r,c in sp:
        refl|={(int(ax*2-r),int(ay*2-c))} | {(r,int(ay*2-c))} | {(int(ax*2-r),c)} | {(int(ax*2-r),int(ay*2-c))}
    for r,c in refl:
        if 0<=r<H and 0<=c<W and out[r][c]==bg: out[r][c]=scat
    return out
